import numpy as np
import pandas as pd
from pandas import SparseArray

_NAME = (
    "SparseArray(np.array([1, 0, 0], dtype=subtype), fill_value=0)"
    ".astype(pd.SparseDtype(subtype, pd.NA)); any/all(skipna=False) "
    "for subtype in int64, uint64, float64, complex128, m8[ns]"
)

_subtypes = ["int64", "uint64", "float64", "complex128", "m8[ns]"]


def _run():
    results = {}
    for subtype in _subtypes:
        arr = SparseArray(
            np.array([1, 0, 0], dtype=subtype), fill_value=0
        ).astype(pd.SparseDtype(subtype, pd.NA))
        results[subtype] = {
            "any(skipna=False)": arr.any(skipna=False),
            "all(skipna=False)": arr.all(skipna=False),
        }
    return results


try:
    probe(_NAME, _run())
except Exception as e:
    probe_exception(_NAME, e)

